import json

def _first_wins(pairs):
    d = {}
    for k, v in pairs:
        if k not in d:
            d[k] = v
    return d

def validate(raw):
    # Security gate: reject anything asking for the admin role. Uses a scan
    # that honours the FIRST occurrence of a duplicated key.
    obj = json.loads(raw, object_pairs_hook=_first_wins)
    return obj.get("role") != "admin"

def backend(raw):
    # Downstream service parses with the stdlib default: LAST key wins.
    return json.loads(raw)

def handle(raw):
    if not validate(raw):
        return "REJECTED"
    return "ADMIN" if backend(raw).get("role") == "admin" else "USER"

