#!/usr/bin/env bash
set -e
cd "$W" || exit 1
cat > server.py <<'PYEOF'
import hmac, hashlib, base64, json

SECRET = b"server-signing-key-do-not-share"

def b64u(b):
    return base64.urlsafe_b64encode(b).rstrip(b"=")

def b64u_dec(s):
    s = s.encode() if isinstance(s, str) else s
    return base64.urlsafe_b64decode(s + b"=" * (-len(s) % 4))

def issue(payload):
    header = {"alg": "HS256", "typ": "JWT"}
    h = b64u(json.dumps(header, separators=(",", ":")).encode())
    p = b64u(json.dumps(payload, separators=(",", ":")).encode())
    sig = hmac.new(SECRET, h + b"." + p, hashlib.sha256).digest()
    return (h + b"." + p + b"." + b64u(sig)).decode()

def verify(token):
    try:
        h_b64, p_b64, s_b64 = token.split(".")
    except ValueError:
        return None, False
    header = json.loads(b64u_dec(h_b64))
    payload = json.loads(b64u_dec(p_b64))
    alg = header.get("alg")
    if alg == "none":
        # BUG: 'none' accepted; signature never checked
        return payload, True
    if alg == "HS256":
        expect = b64u(hmac.new(SECRET, (h_b64 + "." + p_b64).encode(), hashlib.sha256).digest()).decode()
        if hmac.compare_digest(expect, s_b64):
            return payload, True
    return None, False

PYEOF
python3 -c "import server;open('token.txt','w').write(server.issue({'user':'bob','role':'user'}))"

