from urllib.parse import urlencode

REGISTERED = "https://app.example.com/callback"
CLIENT_ID = "client-123"

def _allowed(redirect_uri):
    # BUG: prefix check instead of exact match against the registered URI
    return redirect_uri.startswith("https://app.example.com")

def authorize(client_id, redirect_uri, state):
    if client_id != CLIENT_ID:
        return ("error", "unknown_client")
