import hashlib, base64

_CODES = {
    "STOLEN_CODE_9f8e": {
        "client_id": "client-123",
        "challenge": "E9Melhoa2OwvFrEMTJguCHaoeK1t8URWbuGJSstw-cM",  # S256 of a secret verifier
        "method": "S256",
        "used": False,
    }
}
ACCESS_TOKEN = "ACCESS_TOKEN_ADMIN_42"

def _s256(verifier):
    d = hashlib.sha256(verifier.encode()).digest()
    return base64.urlsafe_b64encode(d).rstrip(b"=").decode()

def token_endpoint(params):
    if params.get("grant_type") != "authorization_code":
        return (400, {"error": "unsupported_grant_type"})
    rec = _CODES.get(params.get("code"))
    if not rec or rec["used"]:
        return (400, {"error": "invalid_grant"})
    if params.get("client_id") != rec["client_id"]:
        return (400, {"error": "invalid_client"})
    ver = params.get("code_verifier")
    # BUG: PKCE is only enforced when a verifier is supplied. Omit it and the
    # bound code_challenge is never checked.
    if ver is not None and _s256(ver) != rec["challenge"]:
        return (400, {"error": "invalid_grant", "detail": "pkce_mismatch"})
    rec["used"] = True
    return (200, {"access_token": ACCESS_TOKEN, "token_type": "Bearer"})

