CATALOG = {"laptop": 500, "mouse": 25, "cable": 5}

def checkout(cart):
    # cart: list of {"sku":..., "qty":...}
    # BUG: no per-line positivity check; line totals summed as-is.
    charge = 0
    delivered = []
    for line in cart:
        sku, qty = line["sku"], line["qty"]
        if sku not in CATALOG:
            return {"accepted": False, "error": "bad_sku"}
        charge += CATALOG[sku] * qty
